def solve():
    n = 120
    max_n1 = 0
    for k in range(2, n + 1):
        for p in range(1, (n // k) + 1):
            n1 = p * (k * (k - 1) // 2) * ((n - k) * (n - k - 1) // 2 - (p - 1) * (k * (k - 1) // 2))
            if n1 > max_n1:
                max_n1 = n1
                best_k = k
                best_p = p
    print(f"Max N1: {max_n1}, k: {best_k}, p: {best_p}")

